function createHelicalTorus(R, r, turns, tubularSegments, radialSegments, color) {
  const points = [];
  for (let i = 0; i <= tubularSegments; i++) {
    const t = (i / tubularSegments) * Math.PI * 2;
    // Helix on torus: param eq
    const theta = t * turns;
    const x = (R + r * Math.cos(theta)) * Math.cos(t);
    const y = (R + r * Math.cos(theta)) * Math.sin(t);
    const z = r * Math.sin(theta);
    points.push(new THREE.Vector3(x, y, z));
  }
  const curve = new THREE.CatmullRomCurve3(points);
  curve.closed = true;
  const geometry = new THREE.TubeGeometry(curve, 200, 0.025, 8, true);
  const material = new THREE.MeshStandardMaterial({
    color: color,
    emissive: color,
    emissiveIntensity: 2.0,
    roughness: 0.2,
    metalness: 0.5,
    transparent: true,
    opacity: 0.8
  });
  return new THREE.Mesh(geometry, material);
}

