}

// Poloidal loops (meridional)
function createPoloidalLoop(R, heightScale, color) {
  const points = [];
  const segments = 100;
  for (let i = 0; i <= segments; i++) {
    const t = (i / segments) * Math.PI * 2;
    // vertical cross-section circle
    const x = R * Math.cos(t);
    const z = R * Math.sin(t) * 0.3; // flattened
    const y = 0.8 * Math.sin(t);
    points.push(new THREE.Vector3(x, y, z));
  }
  const curve = new THREE.CatmullRomCurve3(points);
  curve.closed = true;
  const geometry = new THREE.TubeGeometry(curve, 100, 0.02, 8, true);
  const material = new THREE.MeshStandardMaterial({
    color: color,
    emissive: color,
    emissiveIntensity: 1.8,
    roughness: 0.3,
    metalness: 0.4,
    transparent: true,
    opacity: 0.75
  });
  return new THREE.Mesh(geometry, material);
}

