const contractionEnd = 10;
const ignitionEnd = 13;

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  const posAttr = particleSystem.geometry.attributes.position;
  const posArray = posAttr.array;

  let phase, progress;
  if (t < contractionEnd) {
    phase = 'contraction';
    progress = t / contractionEnd;
  } else if (t < ignitionEnd) {
    phase = 'ignition';
    progress = (t - contractionEnd) / (ignitionEnd - contractionEnd);
  } else {
    phase = 'main';
    progress = Math.min((t - ignitionEnd) / 5, 1);
  }

  if (phase === 'contraction') {
    const hue = 0.08 - progress * 0.04;
    starMat.color.setHSL(hue, 0.9, 0.15 + progress * 0.25);
    starMat.emissive.setHSL(hue, 1.0, 0.1 + progress * 0.3);
    starMat.emissiveIntensity = 0.2 + progress * 1.0;
    starMat.roughness = 0.6 - progress * 0.3;
    starLight.intensity = progress * 3;
    starLight.color.setHSL(hue, 1.0, 0.5);
    starMesh.scale.setScalar(0.7 + progress * 0.5);

    for (let i = 0; i < particleCount; i++) {
      const i3 = i * 3;
      const speed = 0.5 + (12 - radii[i]) * 0.1;
      angles[i] += 0.01 * speed * (1 + progress);
      const targetR = radii[i] * (0.92 + (1 - progress) * 0.08);
      radii[i] = targetR;

      posArray[i3] = radii[i] * Math.cos(angles[i]);
      posArray[i3 + 2] = radii[i] * Math.sin(angles[i]);
      posArray[i3 + 1] = heights[i] * (0.95 - progress * 0.4);
    }
  } else if (phase === 'ignition') {
    const flash = Math.sin(progress * Math.PI);
    const intensity = 2 + flash * 12;
    starMat.emissive.setHex(0xffffff);
    starMat.emissiveIntensity = intensity;
    starMat.color.setHex(0xffffff);
    starMat.metalness = 0.1;
    starMat.roughness = 0.1;
    starLight.intensity = intensity * 2.5;
    starLight.color.setHex(0xfffff0);
    starMesh.scale.setScalar(1.15 - progress * 0.1);

    for (let i = 0; i < particleCount; i++) {
      const i3 = i * 3;
      angles[i] += 0.02;
      posArray[i3] = radii[i] * Math.cos(angles[i]);
      posArray[i3 + 2] = radii[i] * Math.sin(angles[i]);
    }
  } else {
    const pulse = Math.sin(t * 1.5) * 0.03 + 1;
    const hue = 0.11 + Math.sin(t * 0.5) * 0.01;
    starMat.color.setHSL(hue, 0.8, 0.55);
    starMat.emissive.setHSL(hue, 0.7, 0.4);
    starMat.emissiveIntensity = 2.0 + Math.sin(t * 2) * 0.3;
    starLight.intensity = 5 * pulse;
    starLight.color.setHSL(hue, 0.4, 0.8);
    starMesh.scale.setScalar(1.05 * pulse);

    for (let i = 0; i < particleCount; i++) {
      const i3 = i * 3;
      const orbitSpeed = 0.3 / (radii[i] * 0.3 + 0.5);
      angles[i] += orbitSpeed * 0.1;
      posArray[i3] = radii[i] * Math.cos(angles[i]);
      posArray[i3 + 2] = radii[i] * Math.sin(angles[i]);
    }
  }

  posAttr.needsUpdate = true;
  diskMesh.rotation.z = t * 0.08;
  diskMesh.rotation.x = Math.PI / 2 + Math.sin(t * 0.2) * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();
